/* SPDX-License-Identifier: Apache-2.0
 * Fifteen authored, unexecuted local record groups. Real original rmw POD types
 * are used, but assigned values here are MODEL DATA, not a native take receipt.
 * This does not install a provider, grant ROS rights or qualify an SDK/Runtime.
 */
#include "gateways/ros2/native_rcl_service_records.h"
#include <cstdio>
#include <cstring>
#include <type_traits>
using namespace uwvm2::ros_gateway::native_rcl_service;
static unsigned checks,failures;
#define CHECK(x) do{++checks;if(!(x)){++failures;std::fprintf(stderr,"FAIL_RCL_SERVICE_RECORD line=%u\n",unsigned(__LINE__));}}while(0)
static wire::binding owner(){return {2,UINT64_C(0x100000001),2,3,4};}
static info::header header(){info::header h{};h.kind=events::event_kind::service_request;h.flags=info::source_time|info::received_time|info::native_request_id;h.writer_size=16;h.request_sequence=INT64_MIN;h.source_timestamp=-42;h.received_timestamp=0;h.writer[0]=0xff;return h;}
static void populate(records& q,std::uint64_t ticket=UINT64_MAX){auto i=q.reserve(ticket);CHECK(i!=records::no_slot);auto& r=q.at(i);r.identity_known=true;r.identity.sequence_number=INT64_MIN;std::memset(r.identity.writer_guid,0,sizeof(r.identity.writer_guid));r.identity.writer_guid[0]=static_cast<std::remove_reference_t<decltype(r.identity.writer_guid[0])>>(0xff);r.native_info.request_id=r.identity;r.native_info.source_timestamp=-42;r.native_info.received_timestamp=0;r.body[0]=99;CHECK(q.enqueue(i,header(),1)==0);}
static void options(){CHECK(records::valid_options(1,0));CHECK(records::valid_options(256,16));CHECK(!records::valid_options(0,0)&&!records::valid_options(257,0)&&!records::valid_options(1,17));}
static void full_ticket_signed_native(){records q{2,8,owner(),7};populate(q);q.at(0).sequence_known=true;CHECK(q.ticket(UINT64_MAX)==0&&q.at(0).identity.sequence_number==INT64_MIN&&q.find_sequence(INT64_MIN)==0);}
static void strict_same_identity(){rmw_request_id_t a{},b{};a.sequence_number=-1;b.sequence_number=-1;CHECK(records::same(a,b));b.writer_guid[15]=1;CHECK(!records::same(a,b));}
static void association(){records q{2,8,owner(),7};populate(q);snapshot out;auto bad=owner();++bad.generation;CHECK(q.peek(bad,7,16,out)==13&&!out.bytes);CHECK(q.peek(owner(),8,16,out)==13&&!out.bytes);}
static void transactional_capacity(){records q{2,8,owner(),7};populate(q);snapshot out;out.sequence=123;CHECK(q.peek(owner(),7,16,out,192)==90&&out.sequence==123&&!out.bytes);CHECK(q.peek(owner(),7,16,out)==0&&out.reservation==1);}
static void metadata_extent(){records q{2,8,owner(),7};populate(q);snapshot out;CHECK(q.peek(owner(),7,24,out)==95&&!out.bytes);CHECK(q.peek(owner(),7,16,out)==0&&out.reservation==1);}
static void same_record(){records q{2,8,owner(),7};populate(q);snapshot out;CHECK(q.peek(owner(),7,16,out)==0);info::header h{};CHECK(info::decode(out.bytes.get(),192,out.size-192,h));CHECK(h.correlation==UINT64_MAX&&h.request_sequence==INT64_MIN&&h.source_timestamp==-42&&h.received_timestamp==0&&out.bytes[192]==99);}
static void nonce_cancel_not_reused(){records q{2,8,owner(),7};populate(q);snapshot a,b;CHECK(q.peek(owner(),7,16,a)==0);CHECK(q.cancel(owner(),7,a.sequence,a.reservation)==0);CHECK(q.peek(owner(),7,16,b)==0&&b.reservation>a.reservation);CHECK(q.commit(owner(),7,a.sequence,a.reservation)==13);CHECK(q.commit(owner(),7,b.sequence,b.reservation)==0&&q.at(0).phase==state::delivered);}
static void fixed_history(){records q{1,8,owner(),7};populate(q);snapshot s;CHECK(q.peek(owner(),7,16,s)==0&&q.commit(owner(),7,s.sequence,s.reservation)==0);CHECK(!q.can_reserve()&&q.reserve(2)==records::no_slot&&q.ticket(UINT64_MAX)==0);}
static void per_request_error(){records q{2,8,owner(),7};populate(q);snapshot old,current;CHECK(q.peek(owner(),7,16,old)==0);CHECK(q.request_error(0,110)==0);CHECK(q.commit(owner(),7,old.sequence,old.reservation)==13);CHECK(q.peek(owner(),7,0,current)==0);info::header h{};CHECK(info::decode(current.bytes.get(),192,0,h)&&h.kind==events::event_kind::resource_error&&h.error==110&&h.correlation==UINT64_MAX&&!h.flags);}
static void retired_control(){records q{2,8,owner(),7};populate(q);CHECK(q.retire(0)==0);snapshot s;CHECK(q.peek(owner(),7,0,s)==0);info::header h{};CHECK(info::decode(s.bytes.get(),192,0,h)&&h.kind==events::event_kind::resource_closed&&(h.control_flags&events::event_source_retired));CHECK(q.commit(owner(),7,s.sequence,s.reservation)==0&&q.peek(owner(),7,0,s)==125);}
static void missing_metadata(){records q{2,8,owner(),7};auto i=q.reserve(1);auto h=header();h.flags&=~info::received_time;CHECK(q.enqueue(i,h,0)==95);snapshot s;CHECK(q.peek(owner(),7,16,s)==11&&!s.bytes);}
static void zero_extent(){records q{1,0,owner(),7};auto i=q.reserve(9);CHECK(i==0);auto& r=q.at(i);r.identity_known=true;r.identity.sequence_number=INT64_MIN;r.identity.writer_guid[0]=static_cast<std::remove_reference_t<decltype(r.identity.writer_guid[0])>>(0xff);r.native_info.request_id=r.identity;r.native_info.source_timestamp=-42;CHECK(q.enqueue(i,header(),0)==0);snapshot s;CHECK(q.peek(owner(),7,16,s)==0&&s.size==192);CHECK(q.commit(owner(),7,s.sequence,s.reservation)==0);}
static void terminal_error_then_retirement(){records q{1,0,owner(),7};CHECK(q.control(5)==0);snapshot s;CHECK(q.peek(owner(),7,0,s)==0&&q.commit(owner(),7,s.sequence,s.reservation)==0);CHECK(q.control(22)==125);CHECK(q.retire(0)==0);CHECK(q.peek(owner(),7,0,s)==0);info::header h{};CHECK(info::decode(s.bytes.get(),192,0,h)&&h.kind==events::event_kind::resource_closed&&(h.control_flags&events::event_source_retired));CHECK(q.retire(0)==125);}
static void reject_other_native_record(){records q{1,0,owner(),7};auto i=q.reserve(9);auto& r=q.at(i);r.identity_known=true;r.identity.sequence_number=INT64_MIN;r.identity.writer_guid[0]=static_cast<std::remove_reference_t<decltype(r.identity.writer_guid[0])>>(0xff);r.native_info.request_id=r.identity;r.native_info.source_timestamp=-41;CHECK(q.enqueue(i,header(),0)==22);snapshot out;CHECK(q.peek(owner(),7,16,out)==11&&!out.bytes);r.native_info.source_timestamp=-42;CHECK(q.enqueue(i,header(),0)==0);}
int main(){options();full_ticket_signed_native();strict_same_identity();association();transactional_capacity();metadata_extent();same_record();nonce_cancel_not_reused();fixed_history();per_request_error();retired_control();missing_metadata();zero_extent();terminal_error_then_retirement();reject_other_native_record();std::printf("%s_NATIVE_RCL_SERVICE_RECORDS groups=15 checks=%u failures=%u\n",failures?"FAIL":"PASS",checks,failures);return failures?1:0;}
